        a[1371] = "जमिनीवर"
        a[1372] = "टूरने सर्व्हे फेजमध्ये गेस्ट बेडरूमची सर्व्हे तयारी उघडली आहे; शेवटी सर्व काही पूर्वीसारखे होते. संपूर्ण खोली फिरून पाहण्यासाठी 360 वर टॅप करा."
        a[1373] = "360 टॅब उघडा"
        a[1374] = "खोलीत फिरण्यासाठी चित्र ओढा, आणि झूमसाठी दोन बोटे वापरा. ओढणे मोकळ्या भिंतीवरून सुरू करा: मार्कवरून सुरू केलेले ओढणे तो मार्कच हलवते."
        a[1375] = "फिरून पाहण्यासाठी ओढा"
        a[1376] = "360 मध्ये पायऱ्यांची पट्टी नाही: तो हद्द आखलेल्या प्रत्येक पृष्ठभागावर एकाच वेळी, प्रत्येक प्रकाराने मार्क करतो."
        a[1377] = "360 मध्ये पायऱ्या नाहीत"
        a[1378] = "पॅलेट पृष्ठभागावर चालते तसेच इथेही चालते, आणि \"आणखी ▸\" मध्ये प्रत्येक पृष्ठभागाचा प्रत्येक प्रकार असतो."
        a[1379] = "सर्वांसाठी एकच पॅलेट"
        a[1380] = "\"इलेक्ट्रिक\" वर टॅप करा. 360 मध्येही पृष्ठभागाप्रमाणेच निवडलेला प्रकार निवडलेलाच राहतो."
        a[1381] = "पॉइंटचा प्रकार निवडा"
        a[1382] = "टूरने 360 समोरील भिंतीकडे वळवला आहे. सरावासाठी, उजळलेल्या भागात, खिडकीखाली मोकळ्या भिंतीवर टॅप करा: पॉइंट तुमच्या बोटाखालच्या पृष्ठभागावर पडतो, समोरील भिंतीवर FE2. प्रकार फक्त जिथे बसू शकतो तिथेच जातो: जमिनीवर टॅप केलेली खिडकी नाकारली जाते."
        a[1383] = "जिथे आहे तिथे टॅप करा"
        a[1384] = "पृष्ठभागाचा टॅब 360 सोडून, तो पृष्ठभाग ज्या पायरीवर होता तिथे परत नेतो."
        a[1385] = "पृष्ठभागावर परत"
        a[1386] = "360 टॅब: खोलीत फिरून पाहा आणि हद्द आखलेल्या कोणत्याही पृष्ठभागावर थेट मार्क करा."
        a[1387] = "360"
        a[1388] = "टूरने सर्व्हे फेजमध्ये समोरील भिंतीवर गेस्ट बेडरूमचा 360 उघडला आहे; शेवटी सर्व काही पूर्वीसारखे होते. पॅलेट: निवडा, टेप, रेषा, साखळी, इथले सर्वात जास्त लागणारे तीन प्रकार, आणि आणखी ▸."
        a[1389] = "मार्क पॅलेट"
        a[1390] = "एखाद्या ओळीवर टॅप करा, मग तिच्या mm बॉक्समध्ये लेझरचा आकडा टाका; Δ दाखवते की फोटो किती चुकला होता. रीडिंग फक्त सर्व्हे फेजमध्ये घेतले जातात."
        a[1391] = "रीडिंग टाका"
        a[1392] = "Leica D2 चालू असताना D2 वर टॅप करा, त्याचे रीडिंग चालू ओळीत येते. टूर ते दाबत नाही."
        a[1393] = "किंवा D2 ने वाचा"
        a[1394] = "\"दाखवा\" फोटोचे अंदाज (≈ फोटो), लेझर रीडिंग (मोजलेले) आणि दोन्ही एकत्र — यांमध्ये बदलते."
        a[1395] = "फोटो, मोजलेले किंवा दोन्ही"
        a[1396] = "मार्क मोजून झाला की कुलपावर टॅप करा: लॉक केलेला मार्क चुकून बोट लागल्याने हलत नाही की हटत नाही. अनलॉकसाठी पुन्हा टॅप करा."
        a[1397] = "पूर्ण झालेला मार्क लॉक करा"
        a[1398] = "\"इलेक्ट्रिक\" वर टॅप करा — स्विच बोर्ड किंवा सॉकेटसाठीचा पॉइंट. प्रकार निवडलेलाच राहतो, त्यामुळे फोटोवरच्या प्रत्येक टॅपने आणखी एक ठेवला जातो."
        a[1399] = "प्रकार निवडा"
        a[1400] = "चिप सांगते तुम्ही काय ठेवत आहात. सर्व्हे फेजमध्ये प्रत्येक मार्क \"सध्याचे\" म्हणूनच तयार होतो — खोलीत आधीपासून असलेली गोष्ट — त्यामुळे चिपवर आणखी शब्द लागत नाहीत."
        a[1401] = "\"सध्याचे\" म्हणून ठेवले"
        a[1402] = "सरावासाठी, उजळलेल्या भागात मोकळ्या भिंतीवर टॅप करा; साइटवर वस्तू खरोखर जिथे आहे तिथे टॅप करा. मार्कला कोड मिळतो: F म्हणजे समोरील भिंत (Front), E म्हणजे इलेक्ट्रिक (Electric), मग क्रमांक. FE1 आधीच इथे आहे, म्हणून तुमचा FE2. आधीपासून असलेल्या मार्कवर — जसे खिडकी FW1 — टॅप केल्यास दुसरा न ठेवता तोच निवडला जातो."
        a[1403] = "ठेवण्यासाठी टॅप करा"
        a[1404] = "झाल्यावर \"निवडा\" वर टॅप करा. ते विसरणे हे डुप्लिकेट मार्कचे सर्वात मोठे कारण आहे."
        a[1405] = "\"निवडा\" ठेवणे थांबवते"
        a[1406] = "या पृष्ठभागावर लागू शकणाऱ्या इतर सर्व प्रकारांसाठी \"आणखी ▸\" वर टॅप करा."
        a[1407] = "\"आणखी ▸\" मध्ये सर्व प्रकार"
        a[1408] = "प्रकार ट्रेडनुसार गटात आहेत: सिव्हिल, दरवाजे व खिडक्या, इलेक्ट्रिकल, प्लंबिंग आणि बाकीचे. एक निवडा आणि तसाच ठेवा."
        a[1409] = "प्रत्येक ट्रेडची एक ओळ"
        a[1410] = "टूरने \"आणखी ▸\" बंद करून FW1 निवडला आहे — आधीपासून असलेली खिडकी. ही ओळ त्याला थोडे हलवते, लॉक करते किंवा हटवते; त्याचा कोड मार्क तपशील उघडतो."
        a[1411] = "निवडलेला मार्क"
        a[1412] = "3 · यादी मध्ये प्रत्येक मार्कची एक चिप असते, त्यावर झालेली रीडिंग, जसे 0/5. त्या मार्कवर काम करण्यासाठी चिपवर टॅप करा."
        a[1413] = "3 · यादी मध्ये रीडिंग"
        a[1414] = "पॅलेट, प्रकार, मोकळ्या भिंतीवर मार्क ठेवणे, \"आणखी ▸\" आणि त्याच्या ट्रेडच्या ओळी, मग रीडिंग, D2 आणि लॉक."
        a[1415] = "सध्याच्या वस्तू मार्क करा"
        a[1416] = "टूरने \"Demo flat interiors\" हा सरावाचा प्रोजेक्ट उघडला आहे; शेवटी सर्व काही पूर्वीसारखे होते. ही पट्टी त्याची फेज आहे: सर्व्हे, इच्छा-यादी, व्हेंडर तपासणी, अंदाजपत्रक."
        a[1417] = "चार फेज, एक पट्टी"
        a[1418] = "टूरने गेस्ट बेडरूमचा 360 उघडला आहे. वरची पट्टी इथेही फेज दाखवते, आणि ती काय करू देते तेही."
        a[1419] = "सर्व्हे तयारीतील फेज"
        a[1420] = "सर्व्हेमध्ये तुम्ही खोली कॅप्चर करता, भिंतींची हद्द आखता, आधीपासून असलेल्या गोष्टी मार्क करता आणि लेझर रीडिंग घेता. पट्टीखालची ओळ नेहमी सांगते की सध्याची फेज कशासाठी आहे."
        a[1421] = "आधी सर्व्हे"
        a[1422] = "\"इच्छा-यादी\" वर टॅप करा. पुढे जाणे लगेच होते, काहीही न विचारता."
        a[1423] = "इच्छा-यादीकडे जा"
        a[1424] = "इच्छा-यादी फेजपासून पुढे प्रोजेक्टवर \"इच्छा-यादी\" चिप दिसते: ग्राहक मागतो त्या सेवा. सर्व्हेमध्ये ती लपलेली असते."
        a[1425] = "इच्छा-यादी दिसते"
        a[1426] = "कोटेशनचा टप्पा मागोमाग"
        a[1427] = "व्हेंडर तपासणी ग्राहकाच्या इच्छांमधून ट्रेड आणि व्हेंडर पॅक बनवते. या फेजमध्ये ठेवलेला मार्क \"व्हेंडरने जोडले\" म्हणून तयार होतो."
        a[1428] = "मग व्हेंडर तपासणी"
        a[1429] = "अंदाजपत्रक फेज म्हणजे सुपूर्द: नवीन काहीही मार्क होत नाही आणि इच्छा-यादी फक्त वाचण्यासाठी असते. ग्राहकाने अंदाजपत्रक मंजूर केले की ही पट्टी प्रोजेक्टच्या एकाच ओळीत मिटते, आणि तेव्हापासून अल्बममधील कामे प्रोजेक्ट पुढे नेतात."
        a[1430] = "अंदाजपत्रकाकडे सुपूर्द"
        a[1431] = "\"सर्व्हे\" वर टॅप करा. मागे जाणे कधीच गुपचूप होत नाही: फेज बदलण्यापूर्वी अ‍ॅप विचारते."
        a[1432] = "मागे जाताना आधी विचारते"
        a[1433] = "\"ठेवा\" इच्छा-यादीतच ठेवते; \"मागे न्या\" प्रोजेक्ट सर्व्हेवर परत नेते. यांपैकी एकावर टॅप करा."
        a[1434] = "ठेवा किंवा मागे न्या"
        a[1435] = "प्रोजेक्टच्या चार फेज, प्रत्येक काय दाखवते, आणि पुढे किंवा मागे जाणे कसे चालते."
        a[1436] = "फेज"
        a[1437] = "टूरने \"Demo flat interiors\" उघडले आहे आणि शेवटी मांडणी पूर्वीसारखी करते. \"फ्लोअर प्लॅन\" टाइल प्रोजेक्टच्या सर्व्हे झालेल्या खोल्या एका प्लॅनवर मांडते: तिच्यावर टॅप करा."
        a[1438] = "फ्लोअर प्लॅन टाइल"
        a[1439] = "सर्व्हे झालेली प्रत्येक खोली तिच्या लेझर मापांनुसार, दरवाजे व खिडक्यांसह काढलेली असते. \"गेस्ट बेडरूम\" हलवण्यासाठी ओढा."
        a[1440] = "खोली ओढा"
        a[1441] = "खोलीवर टॅप केल्यास ती निवडली जाते आणि ↻ 90° दिसते. खोली पाव वळण फिरवण्यासाठी त्यावर टॅप करा."
        a[1442] = "90° फिरवा"
        a[1443] = "खोली दुसऱ्या खोलीच्या 150 mm आत सोडली की त्यांच्या भिंती कडेला कडा जुळतात. डेमोमध्ये एकच सर्व्हे झालेली खोली आहे, त्यामुळे अजून जुळण्यासारखे काही नाही."
        a[1444] = "कडा आपोआप जुळतात"
        a[1445] = "दोन बोटांनी झूम, आणि कागदावर एका बोटाने सरकवा. \"बसवा\" सर्व खोल्या पुन्हा नजरेत आणते."
        a[1446] = "\"बसवा\" सगळ्या दाखवते"
        a[1447] = "\"मांडणी रीसेट\" विचारून प्रत्येक खोली सुरुवातीच्या ओळीत परत ठेवते. टूर ते दाबत नाही."
        a[1448] = "रीसेट पुन्हा सुरुवात करते"
        a[1449] = "प्रोजेक्टच्या सर्व्हे झालेल्या खोल्या एका प्लॅनवर मांडा: ओढा, 90° फिरवा, आणि कडा जुळू द्या."
        a[1450] = "फ्लोअर प्लॅन"
        a[1451] = "टूरने \"ग्राहक\" उघडले आहे आणि सर्व्हे फेजमध्ये सरावाचा डेटा \"Demo Client\" वापरते; शेवटी सर्व काही पूर्वीसारखे होते. \"Demo Client\" वर टॅप करा."
        a[1452] = "ग्राहकांपासून सुरुवात"
        a[1453] = "2 · मार्क वर टॅप करा. इथे तुम्ही पृष्ठभागावर दरवाजे, खिडक्या आणि पॉइंट ठेवता; \"सध्याच्या वस्तू मार्क करा\" टूर ते कसे ते दाखवते."
        a[1454] = "2 · जे आहे ते मार्क करा"
        a[1455] = "3 · यादी वर टॅप करा: प्रत्येक मार्क, फोटोचा अंदाज, लेझर रीडिंग आणि फरकासह."
        a[1456] = "3 · यादी हाच तक्ता"
        a[1457] = "सहाही पृष्ठभागांची हद्द आखली की \"✓ सेव्ह\" सोनेरी होते, आणि सर्व्हे खोलीच्या फोल्डरमध्ये सेव्ह करते. तसेही तुमचे काम करता करता सेव्ह होत राहते. टूर ते दाबत नाही."
        a[1458] = "सहाही झाल्यावर ✓ सेव्ह"
        a[1459] = "एका ग्राहकाच्या एक किंवा अधिक साइट्स असतात: फ्लॅट, बंगला किंवा ऑफिस. \"Demo Site, Pune\" वर टॅप करा."
        a[1460] = "मग साइट"
        a[1461] = "साइटमध्ये तिचे प्रोजेक्ट असतात, प्रत्येकाच्या स्वतःच्या खोल्या आणि फेज. \"Demo flat interiors\" वर टॅप करा."
        a[1462] = "मग प्रोजेक्ट"
        a[1463] = "फोटो असलेल्या खोल्या आधी येतात, त्यांच्या संख्येसह. \"गेस्ट बेडरूम\" वर टॅप करा."
        a[1464] = "खोली निवडा"
        a[1465] = "साइटवर, \"360 कॅप्चर\" खोलीची तीन लेझर मापे घेतल्यानंतर नवीन 360 काढते. टूर ते दाबत नाही: इथे आधीच काढलेला 360 वापरते."
        a[1466] = "\"360 कॅप्चर\" नवीन सुरू करते"
        a[1467] = "ठेवलेल्या प्रत्येक 360 ची टाइल असते; खालची ओळ सांगते की त्याची सर्व्हे तयारी कुठपर्यंत झाली. सर्व्हे तयारी उघडण्यासाठी चित्रावर टॅप करा."
        a[1468] = "360 उघडा"
        a[1469] = "प्रत्येक पृष्ठभागाला चार रेषा मिळतात: जमिनीची आणि छताची रेषा आणि दोन कोपरे. प्रत्येक रेषा फोटोतील खऱ्या कडेवर ओढा; रेषेला एकदा हात लावला की ती सेट झाली असे धरले जाते."
        a[1470] = "1 · रेषा हद्द आखते"
        a[1471] = "प्रत्येक रेषेची इथे एक ओळ असते, शेवटच्या काही मिलिमीटरसाठी थोडे हलवण्याची बटणे आणि फिरवण्यासाठी ↺ ↻."
        a[1472] = "शेवटचे मिलिमीटर जुळवा"
        a[1473] = "सहाही पृष्ठभागांची हद्द आखा: चार भिंती, जमीन आणि छत. रेषा सेट झाल्या की टॅबवर ✓ दिसते; ही सरावाची खोली आधीच पूर्ण आहे."
        a[1474] = "प्रत्येक पृष्ठभागाला ✓"
        a[1475] = "ग्राहकांपासून खोलीच्या 360 पर्यंत, मग त्याच्या तीन पायऱ्या — 1 · रेषा, 2 · मार्क, 3 · यादी — आणि ✓ सेव्ह."
        a[1476] = "खोलीचा सर्व्हे"
        a[1477] = "टूरने \"Demo flat interiors\" इच्छा-यादी फेजमध्ये उघडला आहे, गेस्ट बेडरूमच्या समोरील भिंतीवर सरावाच्या दोन इच्छांसह; शेवटी सर्व काही पूर्वीसारखे होते. \"व्हेंडर तपासणी\" वर टॅप करा: इच्छा व्हेंडर्सकडे जातात आणि कोटेशनचा टप्पा \"व्हेंडरचे कोटेशन\" होतो."
        a[1478] = "व्हेंडर तपासणीकडे जा"
        a[1479] = "\"⇪ एक्सपोर्ट\" वर टॅप करा. व्हेंडर तपासणीमध्ये एक्सपोर्ट शीट व्हेंडरचा स्वतःचा पॅक देते."
        a[1480] = "एका व्हेंडरसाठी एक्सपोर्ट"
        a[1481] = "टूरने \"दरवाजे व खिडक्या\" निवडले आहे: या पॅकमध्ये फक्त त्या ट्रेडचे मार्क असतात, त्यात FW1, पण इलेक्ट्रिक पॉइंट, ऑफिसच्या नोंदी किंवा ग्राहकाचे नाव कधीच नाही. PDF, PNG किंवा JPEG ने फाइलचा प्रकार ठरतो. टूर तो सेव्ह करत नाही."
        a[1482] = "त्यांचे ट्रेड, PDF किंवा चित्र म्हणून"
        a[1483] = "टूरने गेस्ट बेडरूमच्या 360 चा तपशील उघडला आहे. कोटेशनच्या प्रवासात त्याची \"काम\" ओळ ग्राहकाने अंदाजपत्रक मंजूर करेपर्यंत \"कोटेशनचा प्रवास\" वरच राहते; मग फोटो एखाद्या कामात ठेवला जातो. \"पूर्ण\" सर्व काही पूर्वीसारखे करते."
        a[1484] = "फोटो कामानुसार ठेवले जातात"
        a[1485] = "\"व्हेंडर पॅक\" इच्छा ट्रेडनुसार गटात लावते: खिडकी FW1 \"दरवाजे व खिडक्या\" कडे, इलेक्ट्रिक पॉइंट FE1 \"इलेक्ट्रिकल\" कडे जातो. प्रत्येक आकडा अजून व्हेंडरकडे असलेल्या इच्छा मोजतो."
        a[1486] = "इच्छांचे ट्रेड बनतात"
        a[1487] = "\"दारे-खिडक्या\" खिडकीच्या व्हेंडरचा पॅक बनवते: फक्त त्या ट्रेडचे मार्क, ऑफिसच्या नोंदी नाहीत, ग्राहकाचे नाव नाही. टूर तो इथे उघडत नाही; याच टूरमध्ये पुढे सर्व्हे तयारीचे एक्सपोर्ट तेच करते."
        a[1488] = "प्रत्येक व्हेंडरसाठी एक पॅक"
        a[1489] = "टूरने व्हेंडर तपासणी फेजमध्ये गेस्ट बेडरूमचा 360 उघडला आहे. ट्रेड चिप \"सर्व ▾\" फक्त याच फेजमध्ये असते: एक ट्रेड निवडा आणि सर्व्हे तयारी फक्त त्या व्हेंडरचे मार्क दाखवते."
        a[1490] = "एका ट्रेडचे मार्क दाखवा"
        a[1491] = "टूरने \"इलेक्ट्रिक\" निवडला आहे. या फेजमध्ये चिप \"व्हेंडरने जोडले म्हणून\" जोडते: ग्राहकाच्या इच्छांपलीकडे साइटवर आणखी जे लागते ते व्हेंडरला दिसते."
        a[1492] = "\"व्हेंडरने जोडले\" म्हणून ठेवले"
        a[1493] = "सरावासाठी, उजळलेल्या भागात मोकळ्या भिंतीवर टॅप करा: इलेक्ट्रिशियनला तिथे नवीन पॉइंट हवा आहे. FE2 \"व्हेंडरने जोडले\" म्हणून तयार होतो आणि त्यावर V+ बॅज असतो. टूर शेवटी तो काढून टाकते."
        a[1494] = "व्हेंडरचा मार्क ठेवा"
        a[1495] = "3 · यादी मध्ये आता मार्क वेगवेगळ्या स्थितीत आहेत: सध्याचे, ग्राहकाची इच्छा, आणि FE2 ठेवला असेल तर व्हेंडरने जोडले. सर्व्हेमध्ये प्रत्येक मार्क \"सध्याचे\" असतो, म्हणून तिथे हा फिल्टर दिसत नाही. \"स्थिती ▾\" वर टॅप करा."
        a[1496] = "\"स्थिती ▾\" आता उपयोगी"
        a[1497] = "\"ग्राहकाची इच्छा\" वर टॅप करा: यादीत फक्त दोन इच्छा, FW1 आणि FE1, राहतात. \"सर्व\" पुन्हा प्रत्येक मार्क दाखवते."
        a[1498] = "एक स्थिती निवडा"
        a[1499] = "एक स्थिती निवडलेली असताना \"2 हलवा ▸\" यादीतील प्रत्येक मार्क एकदम पुढे हलवते, इथे दोन्ही इच्छा व्हेंडर तपासणीकडे. जिथे हलवता येते तिथेच ते दिसते, म्हणून सर्व्हे किंवा अंदाजपत्रकात कधीच नाही. टूर ते दाबत नाही."
        a[1500] = "सगळे मिळून पुढे हलवा"
        a[1501] = "व्हेंडर तपासणीकडे जा, इच्छांमधून ट्रेड आणि व्हेंडर पॅक बनलेले पाहा, व्हेंडरचा मार्क ठेवा, स्थितीनुसार फिल्टर करा आणि एका व्हेंडरसाठी एक्सपोर्ट करा."
        a[1502] = "व्हेंडर तपासणी"
        a[1503] = "टूरने \"Demo flat interiors\" हा सरावाचा प्रोजेक्ट उघडला आहे; शेवटी सर्व काही पूर्वीसारखे होते. इच्छा इच्छा-यादी फेजमध्ये सुरू होतात: \"इच्छा-यादी\" वर टॅप करा."
        a[1504] = "इच्छा-यादीकडे जा"
        a[1505] = "मार्क तपशील FW1 \"सध्याचे\" म्हणून दाखवतो. \"→ ग्राहकाची इच्छा\" वर टॅप करा: ग्राहकाला त्यात काही करून हवे आहे."
        a[1506] = "त्याला इच्छा बनवा"
        a[1507] = "ग्राहकाला काय हवे ते निवडा: ↻ बदला, ⇢ हलवा, ⚒ दुरुस्ती किंवा ✕ काढा. \"→ ग्राहकाची इच्छा\" वर टॅप केल्यावर हे चार दिसतात."
        a[1508] = "काय हवे ते सांगा"
        a[1509] = "\"पूर्ण\" वर टॅप करा: FW1 त्या निवडीसह ग्राहकाची इच्छा बनतो."
        a[1510] = "\"पूर्ण\" लागू करते"
        a[1511] = "\"पूर्ण\" नंतर FW1 तुटक रेषेत, \"ग्राहकाची इच्छा\" टॅग आणि त्याच्या निवडीसह काढला जातो: ग्राहकाला त्यात काय करून हवे ते व्हेंडर्सना दिसते. (त्याऐवजी \"पुढे\" दाबले? मग तो अजून \"सध्याचे\" आहे.) टूर संपल्यावर टूरने बदललेले सर्व काही पूर्वीसारखे होते."
        a[1512] = "FW1 आता इच्छा आहे"
        a[1513] = "\"इच्छा-यादी\" चिप दिसू लागली आहे. ग्राहक मागू शकतो त्या सेवा पाहण्यासाठी त्यावर टॅप करा."
        a[1514] = "इच्छा-यादी उघडा"
        a[1515] = "वरचा भाग हव्या असलेल्या सेवा मोजतो. व्हेंडर या यादीवर कोटेशन देतात."
        a[1516] = "ग्राहकाला काय हवे"
        a[1517] = "टिक करण्यासाठी \"इलेक्ट्रिकल कामे\" वर टॅप करा. टिक केलेली सेवा ती कोणत्या खोल्यांना लागू आहे ते आणि एक नोंद दाखवते; व्हेंडर नंतर, \"व्हेंडर तपासणी\" मध्ये जोडला जातो."
        a[1518] = "सेवा टिक करा"
        a[1519] = "बाथरूम नूतनीकरण हा पाच भागांचा एक संच आहे: वॉटरप्रूफिंग, टाइलिंग, प्लंबिंग, इलेक्ट्रिकल पॉइंट आणि रंगकाम; \"भाग ▾\" ते दाखवते. \"कुठे लागू\" खाली निवडलेल्या बाथरूमसाठी टिक केल्यास त्या खोलीसाठी पाचही टिक होतात, आणि प्रत्येक भाग वेगळा अनटिक करता येतो."
        a[1520] = "बाथरूम संच"
        a[1521] = "टूरने गेस्ट बेडरूमचा 360 उघडला आहे. या फेजमध्ये 1 · रेषा नाही आणि रीडिंग नाहीत: तुम्ही ठेवलेला प्रत्येक मार्क ग्राहकाची इच्छा असतो."
        a[1522] = "सर्व्हे तयारीत इच्छा"
        a[1523] = "आधीसारखा प्रकार निवडा; टूरने \"इलेक्ट्रिक\" निवडला आहे. आता चिप \"ग्राहकाची इच्छा म्हणून\" जोडते."
        a[1524] = "\"ग्राहकाची इच्छा\" म्हणून ठेवले"
        a[1525] = "सरावासाठी, उजळलेल्या भागात मोकळ्या भिंतीवर टॅप करा: ग्राहकाला तिथे नवीन स्विच बोर्ड हवा आहे. पॉइंट FE2 \"ग्राहकाची इच्छा\" म्हणून तयार होतो आणि त्यावर \"ग्राहकाची इच्छा\" टॅग असतो. टूर शेवटी तो काढून टाकते."
        a[1526] = "इच्छा ठेवा"
